
#include <cassert>
#include <iostream>
#include "dsalib/binary_search.h"
#include "dsalib/dynamic_programming.h"
#include "dsalib/graph.h"
#include "dsalib/input_parser.h"
#include "dsalib/linked_list.h"
#include "dsalib/stack_queue.h"
#include "dsalib/string_algo.h"
#include "dsalib/tree.h"
using namespace dsalib;
int main(){
    LinkedList<int> l; l.push_back(1); l.push_back(2); l.push_back(3); assert(l.middle()->data==2); l.reverse(); assert(l.front()==3); std::vector<unsigned char> ls=l.serialize(); LinkedList<int> lr=LinkedList<int>::deserialize(ls); assert(lr.size()==3);
    LinkedList<int> a; a.push_back(2); a.push_back(4); LinkedList<int> b; b.push_back(5); b.push_back(6); LinkedList<int> sum=LinkedList<int>::add_two_numbers(a,b); assert(sum.front()==7);
    std::vector<int> nums; nums.push_back(1); nums.push_back(2); nums.push_back(2); nums.push_back(4); assert(BinarySearch::search_sorted(nums,4)==3); assert(BinarySearch::first_occurrence(nums,2)==1); assert(BinarySearch::last_occurrence(nums,2)==2); std::vector<int> rot; rot.push_back(4);rot.push_back(5);rot.push_back(1);rot.push_back(2); assert(BinarySearch::search_rotated(rot,1)==2); assert(BinarySearch::find_peak(rot)>=0);
    std::vector<std::vector<int> > mat(2,std::vector<int>(2)); mat[0][0]=1;mat[0][1]=3;mat[1][0]=5;mat[1][1]=7; assert(BinarySearch::search_matrix(mat,5)); assert(BinarySearch::smallest_divisor(nums,6)==2);
    BST<int> bst; bst.insert(5);bst.insert(3);bst.insert(7); assert(bst.search(3)); bst.erase(3); assert(!bst.search(3)); TreeNode<int>* root=new TreeNode<int>(1); root->left=new TreeNode<int>(2); root->right=new TreeNode<int>(3); assert(BinaryTree<int>::height(root)==2); assert(BinaryTree<int>::diameter(root)==2); std::string ts=BinaryTree<int>::serialize(root); TreeNode<int>* rt=BinaryTree<int>::deserialize(ts); assert(BinaryTree<int>::preorder(rt).size()==3); BinaryTree<int>::destroy(root); BinaryTree<int>::destroy(rt);
    Graph g(4,false); g.add_edge(0,1);g.add_edge(1,2);g.add_edge(2,3); assert(g.bfs(0).size()==4); assert(!g.is_bipartite()==false); Graph dg(3,true); dg.add_edge(0,1);dg.add_edge(1,2); assert(dg.topological_sort().size()==3); assert(dg.dijkstra(0)[2]==2);
    assert(DynamicProgramming::lcs("abcde","ace")==3); std::vector<int> wt; wt.push_back(1);wt.push_back(3);wt.push_back(4); std::vector<int> val; val.push_back(15);val.push_back(20);val.push_back(30); assert(DynamicProgramming::knapsack01(wt,val,4)==35); assert(DynamicProgramming::edit_distance("kitten","sitting")==3); assert(DynamicProgramming::coin_change_min(wt,6)==2); assert(DynamicProgramming::lis(nums)==3);
    ArrayStack<int> st; st.push(9); assert(st.top()==9); Queue<int> q; q.push(8); assert(q.front()==8); std::vector<int> win; win.push_back(1);win.push_back(3);win.push_back(-1);win.push_back(5); assert(StackQueueAlgorithms::sliding_window_max(win,2)[0]==3); LRUCache<int,int> cache(1); cache.put(1,2); int out=0; assert(cache.get(1,out)&&out==2);
    assert(StringAlgo::kmp_search("ababa","aba").size()==2); assert(StringAlgo::anagram("listen","silent")); assert(StringAlgo::palindrome("level")); Trie trie; trie.insert("cat"); assert(trie.search("cat")); assert(trie.starts_with("ca"));
    std::vector<unsigned char> enc=InputParser::encode_array(nums); InputParser p(enc); assert(p.parse_array().size()==4); std::vector<unsigned char> gl=InputParser::encode_graph(g); InputParser gp(gl); Graph g2=gp.parse_graph(); assert(g2.size()==4); std::vector<unsigned char> ll=InputParser::encode_linked_list(nums); InputParser lp(ll); assert(lp.parse_linked_list().size()==4);
    std::cout << "dsalib tests passed\n"; return 0; }
